I'm implementing a dependency resolver that processes a list of packages. Each package may have transitive dependencies. Analyze this code for performance issues:

```rust
pub fn resolve_all(packages: &[Package]) -> Result<Vec<ResolvedPackage>> {
    let mut resolved = Vec::new();
    for pkg in packages {
        let deps = fetch_dependencies(&pkg.name)?;
        for dep in &deps {
            if !resolved.iter().any(|r: &ResolvedPackage| r.name == dep.name) {
                let sub_deps = fetch_dependencies(&dep.name)?;
                for sub in &sub_deps {
                    if !resolved.iter().any(|r: &ResolvedPackage| r.name == sub.name) {
                        resolved.push(resolve_single(sub)?);
                    }
                }
                resolved.push(resolve_single(dep)?);
            }
        }
        resolved.push(resolve_single(pkg)?);
    }
    Ok(resolved)
}

fn resolve_single(pkg: &Package) -> Result<ResolvedPackage> {
    let metadata = fs::read_to_string(&pkg.manifest_path)?;
    let parsed: serde_json::Value = serde_json::from_str(&metadata)?;
    let name = parsed["name"].as_str().unwrap_or("").to_string();
    let version = parsed["version"].as_str().unwrap_or("").to_string();
    Ok(ResolvedPackage { name, version, path: pkg.path.clone() })
}
