Review this tarball extraction function for performance. It's used to extract GitHub tarballs to cache:

```rust
pub fn extract_tarball(data: &[u8], dest: &Path, strip_components: usize) -> Result<usize> {
    let decoder = GzDecoder::new(data);
    let mut archive = Archive::new(decoder);
    let mut count = 0;

    for entry in archive.entries()? {
        let mut entry = entry?;
        let path = entry.path()?.to_path_buf();
        let components: Vec<_> = path.components().collect();
        if components.len() <= strip_components {
            continue;
        }
        let rel: PathBuf = components[strip_components..].iter().collect();
        let target = dest.join(&rel);

        if entry.header().entry_type().is_dir() {
            fs::create_dir_all(&target)?;
        } else {
            if let Some(parent) = target.parent() {
                fs::create_dir_all(parent)?;
            }
            let mut contents = Vec::new();
            entry.read_to_end(&mut contents)?;
            fs::write(&target, &contents)?;
        }
        count += 1;
    }
    Ok(count)
}
